output_text:
[
  {
    "id": "exit_only_after_cart_returned",
    "text": "Exit is forbidden unless the shopping cart is parked in the designated return cell at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "at(0,1)",
              "LEAVE_CART"
            ]
          },
          "post": "cart_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_in_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "taken_cart_must_be_returned",
    "text": "Any cart that is picked up must eventually be returned to the cart-return area at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_station": "at(1,5)",
        "cart_return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": {
            "and": [
              "cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "Putting down a shopping cart is forbidden anywhere except the designated cart-return cell at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_exit_with_cart",
    "text": "Customers are forbidden to leave the store while still possessing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "attempt_exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "attempt_exit_with_cart"
    }
  },
  {
    "id": "items_must_be_picked_with_cart",
    "text": "Picking up an item from a shelf is forbidden unless the customer is currently using a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "item_pickup_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carried_items",
    "text": "Customers are forbidden to carry merchandise by hand while moving through the store.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "move_with_hand_item": {
          "pre": {
            "and": [
              "MOVE",
              "carrying_item_by_hand"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_with_hand_item"
    }
  },
  {
    "id": "cart_free_exit_corridor",
    "text": "Shopping carts are forbidden in the pedestrian exit corridor along the bottom row from (2,5) to (9,5).",
    "abstraction": {
      "state_properties": {
        "exit_corridor": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_enters_exit_corridor": {
          "pre": {
            "and": [
              "MOVE",
              "pushing_cart",
              "exit_corridor"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart",
          "exit_corridor"
        ]
      }
    }
  },
  {
    "id": "leave_return_bay_south",
    "text": "After returning a cart at (0,1), the customer may leave that bay only by taking the southward pedestrian lane.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)",
        "cart_has_been_returned_here": {
          "and": [
            "at_return_bay",
            "cart_in_return_bay"
          ]
        }
      },
      "events": {
        "wrong_departure_from_return_bay": {
          "pre": {
            "and": [
              "cart_has_been_returned_here",
              {
                "or": [
                  "N",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        },
        "allowed_south_departure_from_return_bay": {
          "pre": {
            "and": [
              "cart_has_been_returned_here",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "wrong_departure_from_return_bay"
    }
  }
]
